	// multi-machine sessions). This loops over every checkpoint of the turn
	// against one store, so both fetch paths need their own memo or a dead
	// network costs the budget N times: gitRefsStore.fetchFailure covers refs,
	// and hookBlobFetcher memoizes an exhausted blob fetch. Neither memo detects
	// a slow remote whose fetches succeed just under budget, so the turn-end
	// deadline bounds this network phase as a whole. Only this phase checks it:
	// the preparation above is local work, and the deadline exists to stop slow
	// fetches.
	networkCtx := ctx
	if !deadline.IsZero() {
		var cancel context.CancelFunc
		networkCtx, cancel = context.WithDeadline(ctx, deadline)
		defer cancel()
	}
	if networkCtx.Err() != nil {
		abandonInterruptedFinalize(logCtx, state, networkCtx.Err())
		return 0
	}
	stores, err := checkpoint.Open(networkCtx, repo, s.hookCheckpointStoreOptions(networkCtx))
	if err != nil {
		if networkCtx.Err() != nil {
			abandonInterruptedFinalize(logCtx, state, networkCtx.Err())
			return 0
		}
		logging.Warn(logCtx, "finalize: failed to open checkpoint store",
			slog.String("error", err.Error()),
		)
		return 1 // Count as error - all checkpoints will be skipped
	}
	store := stores.Persistent

	precomputed := precomputeTranscriptBlobsForFinalize(logCtx, repo, redactedTranscript, state)

	updateOpts := checkpoint.UpdateOptions{
		SessionID:               state.SessionID,
		Transcript:              redactedTranscript,
		Assets:                  finalizeAssets,
		PreserveAssetsWhenEmpty: sidecarCapable || !externalizationRan,
		Prompts:                 prompts,
		Agent:                   state.AgentType,
		SkillEvents:             skillEvents,
		PrecomputedBlobs:        precomputed,
	}
	errCount, interrupted := finalizeTurnCheckpointWrites(networkCtx, logCtx, store, state, updateOpts)
	if interrupted > 0 {
		recordInterruptedFinalize(logCtx, state, interrupted, networkCtx.Err())
	}

	// Clear turn checkpoint IDs. Do NOT update CheckpointTranscriptStart here — it was
	// already set correctly by PostCommit: condenseAndUpdateState sets it to the total
	// transcript lines when condensing, and carryForwardRemainingFiles resets it to 0
	// when carry-forward is active. Overwriting here would break carry-forward by making
	// sessionHasNewContent think the transcript is fully consumed (no growth).
	state.TurnCheckpointIDs = nil

	return errCount
}

func finalizeTurnCheckpointWrites(
	ctx context.Context,
	logCtx context.Context,
	store checkpoint.PersistentStore,
	state *SessionState,
	updateOpts checkpoint.UpdateOptions,
) (errCount, interrupted int) {
	for checkpointIndex, cpIDStr := range state.TurnCheckpointIDs {
		if ctx.Err() != nil {
			return errCount, len(state.TurnCheckpointIDs) - checkpointIndex
		}

		cpID, err := id.NewCheckpointID(cpIDStr)
		if err != nil {
			logging.Warn(logCtx, "finalize: invalid checkpoint ID, skipping",
				slog.String("checkpoint_id", cpIDStr),
				slog.String("error", err.Error()),
			)
			errCount++
			continue
		}

		updateOpts.CheckpointID = cpID
		if err := store.Write(ctx, checkpoint.SessionTranscript(updateOpts)); err != nil {
			if ctx.Err() != nil {
				return errCount, len(state.TurnCheckpointIDs) - checkpointIndex
			}
			logging.Warn(logCtx, "finalize: failed to update checkpoint",
				slog.String("checkpoint_id", cpIDStr),
				slog.String("error", err.Error()),
			)
			errCount++
			continue
		}

		logging.Info(logCtx, "finalize: checkpoint updated with full transcript",
			slog.String("checkpoint_id", cpIDStr),
			slog.String("session_id", state.SessionID),
		)
	}
	return errCount, 0
}

}

func (s *fanoutStore) ReadSessionMetadataAndPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*Metadata, string, error) {
	return s.primary.ReadSessionMetadataAndPrompts(ctx, checkpointID, sessionIndex) //nolint:wrapcheck // pure delegation to primary
}

func (s *fanoutStore) ListTasks(ctx context.Context, checkpointID id.CheckpointID) ([]TaskEntry, error) {
	return s.primary.ListTasks(ctx, checkpointID) //nolint:wrapcheck // pure delegation to primary
}

func (s *fanoutStore) ReadTaskTranscript(ctx context.Context, checkpointID id.CheckpointID, toolUseID string) ([]byte, error) {
	return s.primary.ReadTaskTranscript(ctx, checkpointID, toolUseID) //nolint:wrapcheck // pure delegation to primary
}

// Write applies to the primary first; only on primary success does it fan out to
// each mirror best-effort. A mirror error is logged and dropped.
func (s *fanoutStore) Write(ctx context.Context, req WriteRequest) error {
	if err := s.primary.Write(ctx, req); err != nil {
		return err //nolint:wrapcheck // primary error is the operation's error, surfaced verbatim
	}
	for i, mirror := range s.mirrors {
		if err := mirror.Write(ctx, req); err != nil {
			logging.Warn(ctx, "checkpoint mirror write failed; primary write succeeded",
				"mirror_index", i, "error", err.Error())
		}
	}
	return nil
}

