		// another reason as the deadline passed; keep that error visible.
		logging.Warn(logCtx, "finalize: checkpoint write failed as the context ended",
			slog.String("checkpoint_id", cpIDStr),
			slog.String("error", err.Error()),
		)
		return

// The deadline also covers transcript preparation and the store open,
// so it leaves room for a slow runner to reach the first fetch.
{name: "deadline_expires_mid_loop", deadline: func() time.Time { return time.Now().Add(3 * time.Second) },

